{
  "name": "opencode-goal-mode-deepcode",
  "version": "1.1.2",
  "description": "OpenCode Goal Mode — goal agent + server plugin: goal_set, idle evaluator (deterministic + LLM), auto-continue until YES. Status machine, budgets, scope guard, persistence, goal history, slash commands.",
  "type": "module",
  "exports": {
    "./package.json": "./package.json"
  },
  "engines": {
    "node": ">=20.11"
  },
  "packageManager": "npm@11.13.0",
  "bin": {
    "opencode-goal-mode": "scripts/install.mjs",
    "opencode-goal-mode-install": "scripts/install.mjs"
  },
  "files": [
    "agents/",
    "commands/",
    "plugins/",
    "scripts/install.mjs",
    "scripts/postinstall.mjs",
    "scripts/benchmark.mjs",
    "skills/",
    "ARCHITECTURE.md",
    "CHANGELOG.md",
    "CODE_OF_CONDUCT.md",
    "CONTRIBUTING.md",
    "CUSTOMIZE.md",
    "GOAL.md",
    "LICENSE",
    "README.md",
    "SECURITY.md"
  ],
  "scripts": {
    "test": "node --test",
    "lint": "biome lint plugins/ scripts/ tests/",
    "lint:fix": "biome lint --write plugins/ scripts/ tests/",
    "install:local": "node scripts/install.mjs",
    "install:global": "node scripts/install.mjs --global",
    "benchmark": "node scripts/benchmark.mjs",
    "postinstall": "node scripts/postinstall.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "goal-mode",
    "ai-agents"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/deepcode-ai-sys/opencode-goal-mode-deepcode.git"
  },
  "bugs": {
    "url": "https://github.com/deepcode-ai-sys/opencode-goal-mode-deepcode/issues"
  },
  "homepage": "https://github.com/deepcode-ai-sys/opencode-goal-mode-deepcode#readme",
  "license": "MIT",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.17.9",
    "@opencode-ai/sdk": "1.17.15"
  },
  "devDependencies": {
    "@biomejs/biome": "2.5.2"
  }
}
